/// One test for all snippets: translated code keeps static state and must stay on one thread.
#[test]
fn translated_snippets_match_csharp() {
    let mut failed = Vec::new();
    for (name, f, expected, source) in CASES {
        let got = match std::panic::catch_unwind(|| crate::rt::run(|| unsafe { f() })) {
            Ok(Ok(s)) => s.get().unwrap_or("<null>").to_owned(),
            Ok(Err(e)) => format!("<exception {e}>"),
            Err(_) => "<panic>".to_owned(),
        };
        if got != *expected {
            failed.push(format!("{name}\n  expected ({source}): {expected}\n  got:      {got}"));
        }
    }
    assert!(failed.is_empty(), "{} of {} snippets differ:\n{}", failed.len(), CASES.len(), failed.join("\n"));
}
